def unpack(blob):
    return gzip.decompress(base64.b85decode(blob.encode()))

def run(*args):
    print("+", " ".join(map(str,args)))
    subprocess.run([sys.executable, *map(str,args)], check=True)

def apply_patch(folder, patch):
    for filename, ops in patch.items():
        path = Path(folder) / filename
        with open(path, "r", encoding="cp932", errors="surrogateescape", newline="") as f:
            lines = f.read().splitlines(keepends=True)
        for op in sorted(ops, key=lambda item: item["start"], reverse=True):
            before, after, i = op["before"], op["after"], op["start"]
            if lines[i:i+len(before)] != before:
                raise RuntimeError(f"Patch precondition failed in {filename} at line {i+1}; expected={before!r}; actual={lines[i:i+len(before)]!r}")
            lines[i:i+len(before)] = after
        with open(path, "w", encoding="cp932", errors="surrogateescape", newline="") as f:
            f.write("".join(lines))

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument("input_script", help="user-supplied original script.arc or ZIP bundle containing script_sw/")
    ap.add_argument("output_script_arc", help="path for rebuilt Switch script.arc")
    ap.add_argument("--keep-work", action="store_true", help="keep temporary build directory for inspection")
    a=ap.parse_args()
    checkpoint=unpack(CHECKPOINT_B85)
    actual=hashlib.sha256(checkpoint).hexdigest()
    if actual != EXPECTED_CHECKPOINT_SHA256:
        raise SystemExit(f"Embedded review checkpoint SHA-256 mismatch: {actual}")
    patch=json.loads(unpack(PATCH_B85))
    with tempfile.TemporaryDirectory(prefix="lovepical_build_") as tmp:
        work=Path(tmp)
        input_path=Path(a.input_script).resolve()
        jp_copy=work/"script_jp"
        if zipfile.is_zipfile(input_path):
            with zipfile.ZipFile(input_path) as z:
                z.extractall(work / "input")
            candidates=list((work/"input").rglob("script_sw"))
            if len(candidates)!=1 or not candidates[0].is_dir():
                raise SystemExit("Input ZIP must contain exactly one script_sw/ directory")
            jp=candidates[0]
            if not (jp/"_index.txt").is_file():
                raise SystemExit("ZIP bundle is missing script_sw/_index.txt. Use the original script.arc instead; extraction generates the index in archive order.")
            shutil.copytree(jp,jp_copy)
        else:
            if not input_path.is_file():
                raise SystemExit(f"Input file does not exist: {input_path}")
            # custom_arc extract creates _index.txt from the original entry order.
            run(Path(__file__).with_name("custom_arc.py"), "extract", input_path, jp_copy)
        review=work/"review_all_filled_pass5.tsv"
        review.write_bytes(checkpoint)
        nm=work/"name_map.tsv"; nm.write_bytes(unpack(NAME_MAP_B85))
        tags=work/"tag_texts.tsv"; tags.write_bytes(unpack(TAG_TEXTS_B85))
        en=work/"script_en"; ready=work/"script_ready"; tagged=work/"script_tagged"; choices=work/"script_choices"; final=work/"script_final"
        run(Path(__file__).with_name("align_apply.py"), review, "--src-dir", jp_copy, "--out-dir", en)
        run(Path(__file__).with_name("script_postprocess.py"), "--src-dir", en, "--out-dir", ready, "--name-map", nm)
        run(Path(__file__).with_name("tag_texts.py"), "apply", tags, "--src-dir", ready, "--out-dir", tagged)
        run(Path(__file__).with_name("apply_choice_translations.py"), "--src-dir", tagged, "--jp-dir", jp_copy, "--out-dir", choices, "--review", work/"choice_review.tsv")
        run(Path(__file__).with_name("strip_italic_tags.py"), choices, final)
        apply_patch(final, patch)
        output=Path(a.output_script_arc).resolve(); output.parent.mkdir(parents=True,exist_ok=True)
        run(Path(__file__).with_name("custom_arc.py"), "pack", final, output)
        digest=hashlib.sha256(output.read_bytes()).hexdigest()
        if digest != EXPECTED_ARC_SHA256:
            raise SystemExit("Build completed, but output does NOT match the canonical v6.7.11 archive.\n"
                             f"Expected SHA-256: {EXPECTED_ARC_SHA256}\nActual SHA-256:   {digest}\n"
                             "Do not treat this as a reproducible build; inspect the input scripts and tool versions.")
        run(Path(__file__).with_name("custom_arc.py"), "verify", output)
        print(f"\nSUCCESS: byte-identical v6.7.11 archive\nSHA-256: {digest}\nBytes: {output.stat().st_size}")
        if a.keep_work:
            keep=output.with_suffix(".build_work")
            if keep.exists(): shutil.rmtree(keep)
            shutil.copytree(work,keep)
            print(f"Work files copied to: {keep}")

if __name__ == "__main__":
    main()
